import java.io.InputStreamReader;
import java.io.IOException;
import java.util.HashMap;
import java.io.BufferedReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.io.Reader;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 * @author Vadim
 */
public class Main {
	public static void main(String[] args) {
		InputStream inputStream = System.in;
		OutputStream outputStream = System.out;
		InputReader in = new InputReader(inputStream);
		PrintWriter out = new PrintWriter(outputStream);
		TaskC solver = new TaskC();
		solver.solve(1, in, out);
		out.close();
	}
}

class TaskC {
    long[] a = new long[17];
    HashMap<Long, Long> cache = new HashMap<Long, Long>();

    private long calc(long n) {
        if (n == 0) {
            return 0;
        }
        if (cache.containsKey(n)) {
            return cache.get(n);
        }

        long minDigits = Long.MAX_VALUE;

        for (int i = 0; i < 17; i++) {
            if (a[i] > n) {
                break;
            }

            // Use a[i] as many times as possible
            long count = n / a[i];
            long remainder = n % a[i];
            long digits = count * (i + 1) + calc(remainder);
            minDigits = Math.min(minDigits, digits);

            // Try using one more of a[i] and subtract
            if (i > 0 && a[i] > n) {
                long diff = a[i] - n;
                long digits2 = (i + 1) + calc(diff);
                minDigits = Math.min(minDigits, digits2);
            }
        }

        cache.put(n, minDigits);
        return minDigits;
    }

    public void solve(int testNumber, InputReader in, PrintWriter out) {
        int n = in.nextInt();

        a[0] = 1;
        for (int i = 1; i < 17; i++) {
            a[i] = a[i-1] * 10 + 1;
        }

        out.println(calc(n));
    }
}

class InputReader extends BufferedReader {
    public InputReader(InputStream st) {
        super(new InputStreamReader(st));
    }

    public int nextInt() {
        try {
            int c = read();

            while (isWhiteSpace(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int ret = 0;
            while (c >= 0 && !isWhiteSpace(c)) {
                if (c < '0' || c > '9') {
                    throw new RuntimeException();
                }
                ret = ret * 10 + c - '0';
                c = read();
            }
            return ret * sgn;
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    public String readLine() {
        try {
            return super.readLine();
        } catch (IOException e) {
            return null;
        }
    }

    static boolean isWhiteSpace(int c) {
        return c >= 0 && c <= 32;
    }
}
